                                                                                                                                                                                                                                                                                  sent_ok = voice_handler.send_sms(
                                                                                                                                                                                                                                                                                                      to_number=caller_number,
                                                                                                                                                                                                                                                                                                                          message=f"Hi! Here's the Lash Zone London booking link: {os.environ.get('BOOKING_URL', 'https://lashzonelondon.com')}",
                                                                                                                                                                                                                                                                                                                                          )
